import type { Browser, BrowserContext } from "playwright-core";
import { desktopRender, isDesktop } from "@/lib/desktop-bridge";
import { loopbackUrl } from "@/lib/env";

export type Shot = { label: string; path: string; width: number; height: number; full: boolean; root: string; theme: "light" | "dark" };
export type Seen = { label: string; png: Uint8Array; problems: string[] };

export function layoutProblems(selector: string, theme: string): string[] {
  const root = document.querySelector(selector);
  if (!root) return ["Nothing was drawn."];
  const problems: string[] = [];
  const page = selector === "body";
  const name = (element: Element) => {
    const text = (element.textContent ?? "").trim().replace(/\s+/g, " ");
    return text ? `"${text.slice(0, 40)}${text.length > 40 ? "…" : ""}"` : `a <${element.tagName.toLowerCase()}>`;
  };
  const shown = (element: Element) => {
    const rect = element.getBoundingClientRect(), style = getComputedStyle(element);
    return rect.width > 0 && rect.height > 0 && style.visibility !== "hidden" && Number(style.opacity) > 0.05;
  };
  const leaves = [...root.querySelectorAll("*")].filter(element => {
    const tag = element.tagName.toLowerCase();
    if (element.closest("svg") && tag !== "svg") return false;
    return (tag === "svg" || tag === "canvas" || [...element.childNodes].some(node => node.nodeType === 3 && (node.textContent ?? "").trim())) && shown(element);
  }).slice(0, 400);
  if (!leaves.length) return ["Nothing visible was drawn."];
  const error = document.getElementById("moneo-page-error");
  if (error) problems.push(`A script failed: ${error.textContent ?? ""}`);
  const box = root.getBoundingClientRect();
  if (page) {
    const wide = document.documentElement.scrollWidth;
    if (wide > innerWidth + 1) problems.push(`The page scrolls sideways at ${innerWidth}px wide (it is ${wide}px). Widest: ${leaves.filter(leaf => leaf.getBoundingClientRect().right > innerWidth + 1).slice(0, 3).map(name).join(", ")}`);
  } else {
    for (const leaf of leaves) {
      const rect = leaf.getBoundingClientRect();
      const edge = rect.bottom > box.bottom + 1 ? "bottom" : rect.right > box.right + 1 ? "right" : rect.left < box.left - 1 ? "left" : null;
      if (edge) problems.push(`${name(leaf)} is cut off at the ${edge} edge of the card`);
    }
  }
  const media = (element: Element) => ["svg", "canvas"].includes(element.tagName.toLowerCase());
  const overlay = (element: Element) => getComputedStyle(element).position === "absolute";
  let overlaps = 0;
  for (let i = 0; i < leaves.length && overlaps < 6; i++) for (let j = i + 1; j < leaves.length && overlaps < 6; j++) {
    const a = leaves[i], b = leaves[j];
    if (!a || !b || a.contains(b) || b.contains(a)) continue;
    if ((media(a) && overlay(b)) || (media(b) && overlay(a))) continue;
    const ra = a.getBoundingClientRect(), rb = b.getBoundingClientRect();
    const width = Math.min(ra.right, rb.right) - Math.max(ra.left, rb.left), height = Math.min(ra.bottom, rb.bottom) - Math.max(ra.top, rb.top);
    if (width > 4 && height > 4 && width * height > 40) { problems.push(`${name(a)} overlaps ${name(b)}`); overlaps++; }
  }
  for (const leaf of leaves) {
    const style = getComputedStyle(leaf);
    if (!media(leaf) && parseFloat(style.fontSize) < 10) problems.push(`${name(leaf)} is ${style.fontSize} text, too small to read`);
    if (style.textOverflow === "ellipsis" && leaf.scrollWidth > leaf.clientWidth + 1) problems.push(`${name(leaf)} is shortened with an ellipsis`);
  }
  if (page) {
    const channels = (getComputedStyle(document.body).backgroundColor.match(/[\d.]+/g) ?? []).map(Number);
    const [red = 0, green = 0, blue = 0, alpha = 1] = channels;
    const light = (0.2126 * red + 0.7152 * green + 0.0722 * blue) / 255 > 0.5;
    if (alpha > 0.5 && light === (theme === "dark")) problems.push(`The page ignores ${theme} mode: its background stays ${light ? "light" : "dark"}. Take colours from the --moneo-* variables.`);
  }
  return [...new Set(problems)].slice(0, 20);

